practice.solutionCode:
public class Main {
    public static String describeSign(int n) {
        if (n > 0) {
            return "Positive";
        } else if (n < 0) {
            return "Negative";
        }
        return "Zero";
    }

    public static void main(String[] args) {
        System.out.println("5 is " + describeSign(5));
        System.out.println("-3 is " + describeSign(-3));
        System.out.println("0 is " + describeSign(0));
    }
}

