practiceProblems.solutionCode:
public class Main {
    public static double calcBonus(double salary, boolean isTopPerformer) {
        if (isTopPerformer) {
            return salary * 0.20;
        }
        return salary * 0.05;
    }

    public static void main(String[] args) {
        double bonus = calcBonus(50000.0, true);
        System.out.println("Bonus: $" + bonus);
    }
}

