practiceProblems.solutionCode:
public class Main {
    public static int stepA(int x) {
        return x + 3;
    }

    public static int stepB(int y) {
        return stepA(y) * 2;
    }

    public static int stepC(int z) {
        return stepB(z) - 1;
    }

    public static void main(String[] args) {
        int ans = stepC(5);
        System.out.println("Chain output: " + ans);
    }
}

