practiceProblems.solutionCode:
public class Main {
    public static void countdownSafe(int n) {
        if (n <= 0) {
            System.out.println("Stop");
            return;
        }
        System.out.println(n);
        countdownSafe(n - 1);
    }

    public static void main(String[] args) {
        countdownSafe(3);
    }
}

