practiceProblems.solutionCode:
public class Main {
    public static void recordOrder(int first, int second) {
        System.out.println("first=" + first + ", second=" + second);
    }

    public static void main(String[] args) {
        int counter = 10;
        recordOrder(counter++, counter++);
        System.out.println("counter=" + counter);
    }
}
